"""Per-service settings with least-privilege credential loading.

Each service loads ONLY the secrets it needs. The gateway gets TRTC + Langfuse;
the agent and validator get LLM + Langfuse. Variable names are aliased to match
the user's existing .env exactly.
"""

from __future__ import annotations

from typing import Literal

from pydantic import Field, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict


class _BaseSettings(BaseSettings):
    """Common base — reads from .env, is case-insensitive, never crashes on missing."""

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )


class LangfuseSettings(_BaseSettings):
    """Langfuse credentials shared by all three services."""

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
        env_prefix="LANGFUSE_",
    )

    public_key: str | None = Field(default=None, alias="LANGFUSE_PUBLIC_KEY")
    secret_key: str | None = Field(default=None, alias="LANGFUSE_SECRET_KEY")
    base_url: str | None = Field(default=None, alias="LANGFUSE_BASE_URL")

    @property
    def enabled(self) -> bool:
        return bool(self.public_key and self.secret_key and self.base_url)


class LLMSettings(_BaseSettings):
    """LLM provider credentials for agent and validator (TokenHub, OpenAI-compatible)."""

    # tokenhub_key is the user's exact env var name; LLM_API_KEY is the canonical alias
    api_key: str | None = Field(default=None, alias="tokenhub_key")
    base_url: str = Field(
        default="https://tokenhub-intl.tencentcloudmaas.com/v1",
        alias="LLM_BASE_URL",
    )

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )

    @property
    def enabled(self) -> bool:
        return bool(self.api_key)


class AgentSettings(LLMSettings, LangfuseSettings):
    """Agent service settings: LLM + Langfuse only."""

    extract_model: str = Field(default="hy3", alias="EXTRACT_MODEL")
    gateway_base_url: str = Field(default="http://localhost:8002", alias="GATEWAY_BASE_URL")

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )


class ValidatorSettings(LLMSettings, LangfuseSettings):
    """Validator service settings: LLM + Langfuse only."""

    validate_model: str = Field(default="deepseek-v4-flash", alias="VALIDATE_MODEL")

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )


class TRTCSettings(_BaseSettings):
    """Gateway-only TRTC ASR credentials."""

    sdk_app_id: str | None = Field(default=None, alias="SDKAppID")
    sdk_secret_key: str | None = Field(default=None, alias="SDKSecretKey")
    asr_host: str = Field(default="asr-intl.cloud-rtc.com", alias="TRTC_ASR_HOST")

    @property
    def enabled(self) -> bool:
        return bool(self.sdk_app_id and self.sdk_secret_key)


class GatewaySettings(LangfuseSettings, TRTCSettings):
    """Gateway service settings: TRTC + Langfuse + DB + policy defaults."""

    db_path: str = Field(default="data/dcta.db", alias="DCTA_DB_PATH")
    rp_id: str = Field(default="localhost", alias="WEBAUTHN_RP_ID")
    rp_origin: str = Field(default="http://localhost:5173", alias="WEBAUTHN_RP_ORIGIN")

    # Policy defaults
    nonce_ttl_seconds: int = Field(default=120, alias="NONCE_TTL_SECONDS")
    mandate_per_leg: str = Field(default="1000.00", alias="MANDATE_PER_LEG")
    mandate_daily: str = Field(default="3000.00", alias="MANDATE_DAILY")
    risk_threshold: str = Field(default="500.00", alias="RISK_THRESHOLD")
    cooling_hours: int = Field(default=12, alias="COOLING_HOURS")
    timezone: str = Field(default="Asia/Singapore", alias="DCTA_TIMEZONE")

    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=False,
        extra="ignore",
    )


def load_agent_settings() -> AgentSettings:
    return AgentSettings()


def load_validator_settings() -> ValidatorSettings:
    return ValidatorSettings()


def load_gateway_settings() -> GatewaySettings:
    return GatewaySettings()

"""Per-service settings with least-privilege credential loading.

Each service loads ONLY the secrets it needs. The gateway gets TRTC + Langfuse;
the agent and validator get LLM + Langfuse. Variable names are aliased to match
the user's existing .env exactly.
"""

from __future__ import annotations

from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict

_ENV_CONFIG = SettingsConfigDict(
    env_file=".env",
    env_file_encoding="utf-8",
    case_sensitive=False,
    extra="ignore",
)


class _BaseSettings(BaseSettings):
    """Common base — reads from .env, is case-insensitive, ignores extra vars."""

    model_config = _ENV_CONFIG


class LangfuseSettings(_BaseSettings):
    """Langfuse credentials. Mixed into services that need observability."""

    langfuse_public_key: str | None = Field(default=None, alias="LANGFUSE_PUBLIC_KEY")
    langfuse_secret_key: str | None = Field(default=None, alias="LANGFUSE_SECRET_KEY")
    langfuse_base_url: str | None = Field(default=None, alias="LANGFUSE_BASE_URL")

    @property
    def langfuse_enabled(self) -> bool:
        return bool(self.langfuse_public_key and self.langfuse_secret_key and self.langfuse_base_url)


class LLMSettings(_BaseSettings):
    """LLM provider credentials (TokenHub, OpenAI-compatible). Mixed into agent/validator."""

    llm_api_key: str | None = Field(default=None, alias="tokenhub_key")
    llm_base_url: str = Field(
        default="https://tokenhub-intl.tencentcloudmaas.com/v1",
        alias="LLM_BASE_URL",
    )

    @property
    def llm_enabled(self) -> bool:
        return bool(self.llm_api_key)


class TRTCSettings(_BaseSettings):
    """Gateway-only TRTC ASR credentials."""

    trtc_sdk_app_id: str | None = Field(default=None, alias="SDKAppID")
    trtc_sdk_secret_key: str | None = Field(default=None, alias="SDKSecretKey")
    trtc_asr_host: str = Field(default="asr-intl.cloud-rtc.com", alias="TRTC_ASR_HOST")

    @property
    def trtc_enabled(self) -> bool:
        return bool(self.trtc_sdk_app_id and self.trtc_sdk_secret_key)


class AgentSettings(LLMSettings, LangfuseSettings):
    """Agent service settings: LLM + Langfuse only. No ledger, no signing, no TRTC."""

    extract_model: str = Field(default="hy3", alias="EXTRACT_MODEL")
    gateway_base_url: str = Field(default="http://localhost:8002", alias="GATEWAY_BASE_URL")


class ValidatorSettings(LLMSettings, LangfuseSettings):
    """Validator service settings: LLM + Langfuse only. No ledger, no payment tools."""

    validate_model: str = Field(default="deepseek-v4-flash", alias="VALIDATE_MODEL")


class GatewaySettings(LangfuseSettings, TRTCSettings):
    """Gateway service settings: TRTC + Langfuse + DB + policy defaults."""

    db_path: str = Field(default="data/dcta.db", alias="DCTA_DB_PATH")
    rp_id: str = Field(default="localhost", alias="WEBAUTHN_RP_ID")
    rp_origin: str = Field(default="http://localhost:5173", alias="WEBAUTHN_RP_ORIGIN")

    # Policy defaults (prototype values, not regulatory statements)
    nonce_ttl_seconds: int = Field(default=120, alias="NONCE_TTL_SECONDS")
    mandate_per_leg: str = Field(default="1000.00", alias="MANDATE_PER_LEG")
    mandate_daily: str = Field(default="3000.00", alias="MANDATE_DAILY")
    risk_threshold: str = Field(default="500.00", alias="RISK_THRESHOLD")
    cooling_hours: int = Field(default=12, alias="COOLING_HOURS")
    timezone: str = Field(default="Asia/Singapore", alias="DCTA_TIMEZONE")


def load_agent_settings() -> AgentSettings:
    return AgentSettings()


def load_validator_settings() -> ValidatorSettings:
    return ValidatorSettings()


def load_gateway_settings() -> GatewaySettings:
    return GatewaySettings()

