import { useState, useEffect, useCallback } from 'react'
import { Chat } from './components/Chat'
import { Confirmation } from './components/Confirmation'

export function App() {
  const [gatewayHealth, setGatewayHealth] = useState<string>('checking…')

  const checkHealth = useCallback(async () => {
    try {
      const res = await fetch('/api/gateway/health')
      if (res.ok) {
        const data = await res.json()
        setGatewayHealth(`${data.service}: ${data.status}`)
      } else {
        setGatewayHealth(`HTTP ${res.status}`)
      }
    } catch {
      setGatewayHealth('unreachable')
    }
  }, [])

  useEffect(() => {
    void checkHealth()
  }, [checkHealth])

  return (
    <div className="min-h-screen bg-gray-50">
      <header className="bg-blue-700 text-white px-4 py-3 shadow">
        <h1 className="text-lg font-semibold">DCTA — Direct Conversational Transaction Agent</h1>
        <p className="text-sm text-blue-100">Gateway: {gatewayHealth}</p>
      </header>
      <main className="max-w-2xl mx-auto p-4 space-y-4">
        <Chat />
        <Confirmation />
      </main>
    </div>
  )
}

import { useState, useRef, useEffect } from 'react'

interface Message {
  id: number
  role: 'user' | 'assistant'
  text: string
}

/**
 * Chat placeholder component.
 * T-09 implements the full conversation workflow;
 * T-12 adds voice/microphone capture.
 */
export function Chat() {
  const [messages, setMessages] = useState<Message[]>([
    { id: 0, role: 'assistant', text: 'Welcome. How can I help you with your banking today?' },
  ])
  const [input, setInput] = useState('')
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' })
  }, [messages])

  const send = () => {
    if (!input.trim()) return
    const userMsg: Message = { id: messages.length, role: 'user', text: input.trim() }
    setMessages((prev) => [...prev, userMsg])
    setInput('')
    // Placeholder: the real extraction workflow (T-09) replaces this.
    const placeholder: Message = {
      id: messages.length + 1,
      role: 'assistant',
      text: '(Extraction workflow not yet implemented — T-09)',
    }
    setMessages((prev) => [...prev, placeholder])
  }

  return (
    <section className="bg-white rounded-lg shadow p-4">
      <h2 className="text-sm font-medium text-gray-600 mb-2">Conversation</h2>
      <div
        ref={scrollRef}
        className="h-64 overflow-y-auto space-y-2 border rounded p-3 bg-gray-50"
      >
        {messages.map((m) => (
          <div
            key={m.id}
            className={m.role === 'user' ? 'text-right' : 'text-left'}
          >
            <span
              className={
                m.role === 'user'
                  ? 'inline-block bg-blue-600 text-white rounded-lg px-3 py-1.5 text-sm max-w-xs'
                  : 'inline-block bg-gray-200 text-gray-800 rounded-lg px-3 py-1.5 text-sm max-w-xs'
              }
            >
              {m.text}
            </span>
          </div>
        ))}
      </div>
      <div className="flex gap-2 mt-3">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && send()}
          placeholder="Type your request…"
          className="flex-1 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          onClick={send}
          className="bg-blue-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-blue-700"
        >
          Send
        </button>
      </div>
      {/* T-12: microphone push-to-talk button goes here */}
    </section>
  )
}

/**
 * Confirmation placeholder component.
 * T-05 implements the exact-payload WebAuthn approval flow;
 * T-11 adds the full mandate and evidence views.
 * The confirmation fetches the immutable signing envelope
 * directly from the gateway and renders gateway metadata only.
 */
export function Confirmation() {
  return (
    <section className="bg-white rounded-lg shadow p-4">
      <h2 className="text-sm font-medium text-gray-600 mb-2">Confirmation</h2>
      <div className="border rounded p-3 bg-gray-50 text-sm text-gray-500">
        <p>No active transaction to confirm.</p>
        <p className="mt-1 text-xs">
          (Exact-payload WebAuthn confirmation — T-05/T-11)
        </p>
      </div>
    </section>
  )
}

